use std::collections::HashMap;
use crate::{features::{self,Family,Meta,EVENTS},frontend::Front,model::Cdf};
#[derive(Clone,Copy)]
struct Cell {packed:u32,count:u32}
#[derive(Clone,Copy)]
struct Row {key:u32,start:u32,end:u32,total:u32}
const _:()=assert!(std::mem::size_of::<Cell>()==8 && std::mem::size_of::<Row>()==16);
#[derive(Default,Clone,Copy)]
pub struct Kahan {pub sum:f64,correction:f64}
impl Kahan {pub fn add(&mut self,x:f64)->Result<(),String>{if !x.is_finite() || x<0.0{return Err("loss nonfinite/range".into());}let y=x-self.correction;let sum=self.sum+y;self.correction=(sum-self.sum)-y;self.sum=sum;if !sum.is_finite(){return Err("loss accumulation nonfinite".into());}Ok(())}}
fn vector<T>(capacity:usize)->Result<Vec<T>,String>{let mut v=Vec::new();v.try_reserve_exact(capacity).map_err(|_|"aggregate Vec allocation")?;Ok(v)}
struct Aggregate {cells:Vec<Cell>,rows:Vec<Row>,count_prefix:Vec<u32>,q_freq:Vec<u32>,q_prefix:Vec<u32>,tokens:[u64;2],row_count:[u64;2],cell_count:[u64;2],singleton_rows:[u64;2],singleton_tokens:[u64;2],rowfield_bits:[u64;2],map_capacity:usize,map_bucket_estimate:usize,map_bytes_estimate:usize}
impl Aggregate {
    fn build(front:&Front,family:Family)->Result<(Self,Meta),String>{
        let mut map:HashMap<u32,u32>=HashMap::new();map.try_reserve(EVENTS).map_err(|_|"aggregate map allocation")?;let map_capacity=map.capacity();
        let map_bucket_estimate=map_capacity.checked_mul(8).and_then(|x|x.checked_add(6)).map(|x|x/7).ok_or("map buckets overflow")?;
        if map_capacity<EVENTS || map_bucket_estimate>2097152{return Err("map reservation bound".into());}let map_bytes_estimate=map_bucket_estimate.checked_mul(9).and_then(|x|x.checked_add(16)).ok_or("map bytes overflow")?;
        let meta=features::walk(front,family,|_,key,token,_,_|{let p=features::packed(key,token)?;if !map.contains_key(&p) && map.len()>=EVENTS{return Err("aggregate cells bound".into());}let count=map.entry(p).or_insert(0);*count=count.checked_add(1).ok_or("aggregate count overflow")?;Ok(())})?;
        if map.capacity()!=map_capacity || map.is_empty() || map.len()>EVENTS{return Err("map growth/cell bound".into());}
        let mut cells=vector(map.len())?;for(packed,count)in map.drain(){if count==0{return Err("zero histogram count".into());}cells.push(Cell{packed,count});}drop(map);
        cells.sort_unstable_by_key(|c|c.packed);if cells.windows(2).any(|w|w[0].packed>=w[1].packed){return Err("aggregate unique order".into());}
        let nrows=1+cells.windows(2).filter(|w|w[0].packed>>9!=w[1].packed>>9).count();if nrows>cells.len() || cells.capacity()>EVENTS{return Err("row/cell capacity bound".into());}
        let mut rows=vector(nrows)?;let mut count_prefix=vector(cells.len())?;let mut q_freq=vector(cells.len())?;let mut q_prefix=vector(cells.len())?;
        let mut tokens=[0u64;2];let mut row_count=[0u64;2];let mut cell_count=[0u64;2];let mut singleton_rows=[0u64;2];let mut singleton_tokens=[0u64;2];let mut rowfield_bits=[0u64;2];
        let mut start=0;while start<cells.len(){let key=cells[start].packed>>9;let component=family.component(key)?;let mut end=start+1;while end<cells.len() && cells[end].packed>>9==key{end+=1;}let used=end-start;let a=if component==0{257}else{256};if used==0 || used>a{return Err("row alphabet extent".into());}let mut counts=vec![0u32;a];let mut total=0u32;
            for cell in &cells[start..end]{let symbol=(cell.packed&511) as usize;if symbol>=a || counts[symbol]!=0{return Err("row symbol range/duplicate".into());}counts[symbol]=cell.count;total=total.checked_add(cell.count).ok_or("row total overflow")?;count_prefix.push(total);}
            let cdf=Cdf::quantize(&counts)?;let mut q_total=0u32;for cell in &cells[start..end]{let frequency=cdf.freq[(cell.packed&511) as usize];if frequency==0{return Err("quantized training zero".into());}q_total=q_total.checked_add(frequency).ok_or("Q prefix overflow")?;q_freq.push(frequency);q_prefix.push(q_total);}if q_total!=32768 || total==0{return Err("row prefix total".into());}
            tokens[component]=tokens[component].checked_add(total as u64).ok_or("component total overflow")?;row_count[component]=row_count[component].checked_add(1).ok_or("row count overflow")?;cell_count[component]=cell_count[component].checked_add(used as u64).ok_or("cell count overflow")?;
            if used==1{singleton_rows[component]=singleton_rows[component].checked_add(1).ok_or("singleton rows overflow")?;singleton_tokens[component]=singleton_tokens[component].checked_add(total as u64).ok_or("singleton tokens overflow")?;}
            let cost=(family.bits() as u64).checked_add(24u64.checked_mul(used as u64).ok_or("rowfield product overflow")?).and_then(|x|x.checked_sub(6)).ok_or("rowfield cost overflow")?;rowfield_bits[component]=rowfield_bits[component].checked_add(cost).ok_or("rowfield sum overflow")?;
            rows.push(Row{key,start:u32::try_from(start).map_err(|_|"row index range")?,end:u32::try_from(end).map_err(|_|"row index range")?,total});start=end;
        }
        if rows.len()!=nrows || rows.capacity()>EVENTS || tokens!=meta.tokens || count_prefix.len()!=cells.len() || q_freq.len()!=cells.len() || q_prefix.len()!=cells.len(){return Err("aggregate construction totals".into());}
        Ok((Self{cells,rows,count_prefix,q_freq,q_prefix,tokens,row_count,cell_count,singleton_rows,singleton_tokens,rowfield_bits,map_capacity,map_bucket_estimate,map_bytes_estimate},meta))
    }
    fn score(&mut self,key:u32,token:usize,limit:usize)->Result<(f64,f64),String>{let i=self.rows.binary_search_by_key(&key,|r|r.key).map_err(|_|"score absent row")?;let row=self.rows[i];let start=row.start as usize;let end=row.end as usize;let desired=features::packed(key,token)?;let offset=self.cells[start..end].binary_search_by_key(&desired,|c|c.packed).map_err(|_|"score absent training token")?;let cutoff=self.cells[start..end].partition_point(|c|(c.packed&511)<limit as u32);
        if token>=limit || limit==0 || cutoff==0 || offset>=cutoff{return Err("score truncated range".into());}let index=start+offset;let count=self.count_prefix[index]-if index==start{0}else{self.count_prefix[index-1]};let count_total=self.count_prefix[start+cutoff-1];let frequency=self.q_freq[index];let q_total=self.q_prefix[start+cutoff-1];
        if count==0 || count>count_total || frequency==0 || frequency>q_total{return Err("score prefix/frequency".into());}self.cells[index].count=self.cells[index].count.checked_sub(1).ok_or("replay count excess")?;
        let empirical=(count_total as f64/count as f64).log2();let quantized=(q_total as f64/frequency as f64).log2();if !empirical.is_finite() || !quantized.is_finite() || empirical<0.0 || quantized<0.0{return Err("score finite".into());}Ok((empirical,quantized))
    }
}
pub fn diagnose(front:&Front,family:Family,expected:&Meta)->Result<String,String>{
    let(mut aggregate,built)=Aggregate::build(front,family)?;same_meta(&built,expected)?;let mut empirical=[Kahan::default();2];let mut quantized=[Kahan::default();2];
    let replay=features::walk(front,family,|c,key,t,limit,_|{let(e,q)=aggregate.score(key,t,limit)?;empirical[c].add(e)?;quantized[c].add(q)?;Ok(())})?;same_meta(&built,&replay)?;
    if aggregate.cells.iter().any(|c|c.count!=0){return Err("all-cell replay counts not consumed".into());}
    let eloss=[empirical[0].sum,empirical[1].sum];let qloss=[quantized[0].sum,quantized[1].sum];let total_q=qloss[0]+qloss[1];let metadata_bits=aggregate.rowfield_bits[0].checked_add(aggregate.rowfield_bits[1]).and_then(|x|x.checked_add(32)).ok_or("metadata total overflow")?;let metadata_bytes=metadata_bits.div_ceil(8);let token_bytes=(total_q/8.0).ceil() as u64;let budget=metadata_bytes.checked_add(token_bytes).and_then(|x|x.checked_add(expected.escapes as u64)).and_then(|x|x.checked_add(285+4+2048)).ok_or("family budget overflow")?;
    let cells_bytes=aggregate.cells.capacity()*8;let rows_bytes=aggregate.rows.capacity()*16;let prefix_bytes=(aggregate.count_prefix.capacity()+aggregate.q_freq.capacity()+aggregate.q_prefix.capacity())*4;let source_bytes=front.runs.capacity()*12+2811006+14077+127624+8512+1369112;let score_working_estimate=cells_bytes+rows_bytes+prefix_bytes+source_bytes+4*1024*1024;let drain_working_estimate=aggregate.map_bytes_estimate+cells_bytes+source_bytes+4*1024*1024;if score_working_estimate>160*1024*1024 || drain_working_estimate>160*1024*1024{return Err("family working estimate bound".into());}
    Ok(format!("{{\"family\":\"{}\",\"key_bits\":{},\"tokens\":{:?},\"rows\":{:?},\"cells\":{:?},\"singleton_rows\":{:?},\"singleton_tokens\":{:?},\"empirical_truncated_loss_bits\":{eloss:?},\"Q32768_truncated_loss_bits\":{qloss:?},\"empirical_total_loss_bits\":{:.12},\"Q_total_loss_bits\":{total_q:.12},\"rowfield_bits\":{:?},\"common_row_count_bits\":32,\"naive_metadata_bits\":{metadata_bits},\"naive_metadata_bytes_ceil\":{metadata_bytes},\"Q_token_bytes_ceil\":{token_bytes},\"uniform_escape_bytes\":{},\"framing_bytes\":285,\"model_bitlength_bytes\":4,\"coder_reserve_bytes\":2048,\"Q_training_naive_budget_bytes\":{budget},\"naive_budget_within_483599\":{},\"map_capacity\":{},\"map_buckets_estimate\":{},\"map_bytes_estimate\":{},\"cell_len\":{},\"cell_capacity\":{},\"row_len\":{},\"row_capacity\":{},\"count_prefix_capacity\":{},\"Q_frequency_capacity\":{},\"Q_prefix_capacity\":{},\"score_working_RAM_estimate_bytes\":{score_working_estimate},\"drain_working_RAM_estimate_bytes\":{drain_working_estimate},\"all_aggregate_cell_replay_counts_equal\":true,\"history_checks_build_and_replay\":{},\"training_only\":true,\"actual_model_serialized\":false}}",family.name(),family.bits(),aggregate.tokens,aggregate.row_count,aggregate.cell_count,aggregate.singleton_rows,aggregate.singleton_tokens,eloss[0]+eloss[1],aggregate.rowfield_bits,expected.escapes,budget<=483599,aggregate.map_capacity,aggregate.map_bucket_estimate,aggregate.map_bytes_estimate,aggregate.cells.len(),aggregate.cells.capacity(),aggregate.rows.len(),aggregate.rows.capacity(),aggregate.count_prefix.capacity(),aggregate.q_freq.capacity(),aggregate.q_prefix.capacity(),built.history_checks+replay.history_checks))
}
pub fn same_meta(a:&Meta,b:&Meta)->Result<(),String>{if a.tokens!=b.tokens || a.runs!=b.runs || a.escapes!=b.escapes || a.grammar!=b.grammar || a.history_checks!=b.history_checks{return Err("walk metadata mismatch".into());}Ok(())}
pub fn aggregate_e2e()->Result<usize,String>{
    use crate::frontend::Run;
    let front=Front{runs:vec![Run{symbol:1,length:1,next:2},Run{symbol:2,length:2,next:u32::MAX},Run{symbol:1,length:3,next:u32::MAX},Run{symbol:0,length:1,next:u32::MAX}],primary:0,last_len:7};let mut checks=0;
    for family in [Family::Global,Family::Symbol,Family::Recent,Family::Joint]{let(mut a,meta)=Aggregate::build(&front,family)?;if meta.tokens!=[4,4] || a.tokens!=[4,4] || a.cells.len()>8 || a.rows.windows(2).any(|r|r[0].key>=r[1].key){return Err("hand aggregate sorted/counts".into());}let replay=features::walk(&front,family,|_,key,t,l,_|{let(e,q)=a.score(key,t,l)?;if e<0.0 || q<0.0{return Err("hand aggregate loss".into());}Ok(())})?;same_meta(&meta,&replay)?;if a.cells.iter().any(|c|c.count!=0){return Err("hand all-cell counts".into());}checks+=1;}
    let singleton=Cdf::quantize(&[9,0])?;let tie=Cdf::quantize(&[1,1,1])?;let all=Cdf::quantize(&vec![1;257])?;if singleton.freq!=[32768,0] || singleton.prefix!=[0,32768,32768] || tie.freq!=[10923,10923,10922] || all.prefix.len()!=258 || all.prefix[257]!=32768 || all.freq.contains(&0){return Err("hand quantization/prefix".into());}checks+=3;
    if Cdf::quantize(&[0,0]).is_ok(){return Err("hand empty CDF rejection".into());}checks+=1;Ok(checks)
}
